export const meta = {
  name: 'research-ai-pipeline-concepts',
  description: 'Research highly-cited literature for six AI pipeline concepts plus prompting and architecture; critique for gaps; verify citations',
  phases: [
    { title: 'Research', detail: 'one literature researcher per concept, web search + fetch' },
    { title: 'Critique', detail: 'completeness critic adds missing seminal work' },
    { title: 'Verify', detail: 'citation verifier confirms every paper exists and claims are accurate' },
  ],
}

const CONCEPTS = [
  {
    key: 'hybrid-retrieval',
    title: 'Hybrid Retrieval (sparse + dense + reranking + fusion)',
    scope: 'Lexical retrieval (BM25 and variants), dense retrieval (bi-encoders such as DPR, Contriever, E5, BGE, GTE), learned sparse (SPLADE), late interaction (ColBERT/ColBERTv2/PLAID), score fusion (Reciprocal Rank Fusion by Cormack et al. 2009, convex/linear combination and normalization by Bruch et al. 2023), cross-encoder and LLM rerankers (monoT5, RankGPT, RankZephyr, cross-encoders), query expansion and generation (HyDE, Query2doc, doc2query), benchmarks (BEIR, MTEB, MS MARCO), chunking and metadata filtering, and evaluation (nDCG@k, recall@k, MRR).',
    seeds: 'Robertson & Zaragoza 2009 (BM25 and probabilistic relevance framework); Karpukhin et al. 2020 DPR; Khattab & Zaharia 2020 ColBERT; Santhanam et al. 2022 ColBERTv2; Formal et al. 2021 SPLADE; Cormack, Clarke & Buettcher 2009 Reciprocal Rank Fusion; Bruch, Gai & Ingber 2023 "An Analysis of Fusion Functions for Hybrid Retrieval"; Gao et al. 2022 HyDE; Wang et al. 2023 Query2doc; Nogueira et al. 2020 monoT5; Sun et al. 2023 RankGPT; Thakur et al. 2021 BEIR; Muennighoff et al. 2022 MTEB; Ma et al. 2021 "A Replication Study of Dense Passage Retriever" / hybrid; Izacard et al. 2021 Contriever; Wang et al. 2022 E5; Xiao et al. 2023 BGE (C-Pack).',
  },
  {
    key: 'task-decomposition',
    title: 'Task Decomposition (planning, sub-goal generation, DAG construction, recursive refinement)',
    scope: 'Prompting-based decomposition (Least-to-Most, Decomposed Prompting, Plan-and-Solve, Self-Ask, Successive Prompting), search-based reasoning (Tree of Thoughts, Graph of Thoughts), interleaved reasoning and acting (ReAct), planner-executor separation (ReWOO, Plan-and-Execute, LLMCompiler DAG planning, HuggingGPT), adaptive and recursive decomposition (ADaPT, TDAG), reflection-driven re-planning (Reflexion, Self-Refine), dependency graphs and topological scheduling, decomposition failure modes, and evaluation on multi-step benchmarks (GSM8K, HotpotQA, ALFWorld, WebShop, AgentBench).',
    seeds: 'Zhou et al. 2022 Least-to-Most Prompting; Khot et al. 2022 Decomposed Prompting; Wang et al. 2023 Plan-and-Solve; Press et al. 2022 Self-Ask; Yao et al. 2023 Tree of Thoughts; Besta et al. 2023 Graph of Thoughts; Yao et al. 2022 ReAct; Xu et al. 2023 ReWOO; Kim et al. 2023 LLMCompiler; Shen et al. 2023 HuggingGPT; Prasad et al. 2023 ADaPT; Shinn et al. 2023 Reflexion; Wei et al. 2022 Chain-of-Thought; Dua et al. 2022 Successive Prompting; Hao et al. 2023 Reasoning via Planning (RAP); Wang et al. 2024 "A Survey on LLM-based Autonomous Agents" or Huang et al. 2024 "Understanding the planning of LLM agents: a survey".',
  },
  {
    key: 'answer-verification',
    title: 'Answer Verification (self-consistency, verification chains, LLM-as-judge, fact checking, uncertainty)',
    scope: 'Sampling-based agreement (Self-Consistency, Universal Self-Consistency), verification prompting (Chain-of-Verification, Verify-and-Edit, Self-Ask style checks), hallucination detection (SelfCheckGPT, semantic entropy by Farquhar et al. 2024 in Nature), attribution and factuality scoring (FActScore, RARR, FacTool, ALCE), LLM-as-a-judge and its biases (Zheng et al. 2023 MT-Bench; position bias, verbosity bias, self-preference), iterative refinement and its limits (Self-Refine, CRITIC, Huang et al. 2023 "LLMs cannot self-correct reasoning yet"), multi-agent debate (Du et al. 2023), process vs outcome reward models and verifiers (Cobbe et al. 2021 GSM8K verifiers, Lightman et al. 2023 "Let\'s Verify Step by Step"), calibration and confidence elicitation (Tian et al. 2023, Xiong et al. 2023), rubric-based evaluation (G-Eval, Prometheus), and tool-grounded verification (code execution, unit tests, retrieval checks).',
    seeds: 'Wang et al. 2022 Self-Consistency; Chen et al. 2023 Universal Self-Consistency; Dhuliawala et al. 2023 Chain-of-Verification; Manakul et al. 2023 SelfCheckGPT; Farquhar et al. 2024 semantic entropy (Nature); Min et al. 2023 FActScore; Gao et al. 2022 RARR; Chern et al. 2023 FacTool; Zheng et al. 2023 Judging LLM-as-a-Judge; Madaan et al. 2023 Self-Refine; Gou et al. 2023 CRITIC; Huang et al. 2023 LLMs Cannot Self-Correct Reasoning Yet; Du et al. 2023 Multiagent Debate; Cobbe et al. 2021 Training Verifiers; Lightman et al. 2023 Let\'s Verify Step by Step; Liu et al. 2023 G-Eval; Kim et al. 2023 Prometheus; Tian et al. 2023 Just Ask for Calibration; Xiong et al. 2023 Can LLMs Express Their Uncertainty; Kadavath et al. 2022 Language Models (Mostly) Know What They Know; Zhao et al. 2023 Verify-and-Edit.',
  },
  {
    key: 'parallelization',
    title: 'Parallelization (concurrent LLM calls, DAG scheduling, speculative execution, map-reduce, ensembles)',
    scope: 'Output-level parallel generation (Skeleton-of-Thought), DAG-based parallel function calling (LLMCompiler), parallel tool use, map-reduce and branch-solve-merge patterns (Branch-Solve-Merge, Mixture-of-Agents, "More Agents Is All You Need", Tree of Thoughts BFS), inference-level parallelism and its implications for client design (speculative decoding by Leviathan et al. 2023 and Chen et al. 2023, Medusa, continuous batching in Orca, PagedAttention in vLLM, Parrot semantic variables), asynchronous orchestration and rate limiting (token bucket, backpressure, retries with jitter, circuit breakers), Amdahl\'s law applied to LLM pipelines, prompt-cache-aware fan-out timing, cost-latency tradeoffs, and failure handling in concurrent pipelines (partial failure, timeouts, idempotency).',
    seeds: 'Ning et al. 2023 Skeleton-of-Thought; Kim et al. 2023 LLMCompiler; Saha et al. 2023 Branch-Solve-Merge; Wang et al. 2024 Mixture-of-Agents; Li et al. 2024 More Agents Is All You Need; Leviathan et al. 2023 Fast Inference via Speculative Decoding; Chen et al. 2023 Accelerating LLM Decoding with Speculative Sampling; Cai et al. 2024 Medusa; Yu et al. 2022 Orca; Kwon et al. 2023 vLLM PagedAttention; Lin et al. 2024 Parrot (OSDI); Zheng et al. 2023 SGLang; Amdahl 1967; Dean & Ghemawat 2004 MapReduce; Nygard "Release It!" stability patterns (circuit breaker, bulkhead); Khattab et al. 2023 DSPy for programmatic composition.',
  },
  {
    key: 'caching',
    title: 'Caching (exact-match memoization, semantic caching, prompt/prefix caching, KV reuse, invalidation)',
    scope: 'Exact-match response caching and key design (normalization, canonical JSON, hashing), semantic caching with embedding similarity thresholds and false-hit risks (GPTCache by Bang 2023, MeanCache, SCALM, "approximate caching" by Gill et al. 2024), provider-side prompt/prefix caching economics and prefix-stability design (Anthropic prompt caching documentation; write cost 1.25x, read cost 0.1x, 5-minute vs 1-hour TTL), KV-cache reuse systems (Prompt Cache by Gim et al. 2023, RadixAttention in SGLang, CacheBlend, CacheGen, Hydragen shared-prefix attention), classical cache theory (LRU/LFU/ARC/TinyLFU, Belady, TTL and staleness, cache stampede/thundering herd, negative caching), invalidation and versioning strategies (prompt version in key, model version in key, dependency-based invalidation), consistency and correctness risks of serving cached LLM outputs, and metrics (hit rate, cost saved, p50/p99 latency, staleness).',
    seeds: 'Bang 2023 GPTCache; Gill et al. 2024 Privacy-aware / approximate caching for LLM (MeanCache); Gim et al. 2023 Prompt Cache: Modular Attention Reuse; Zheng et al. 2023 SGLang RadixAttention; Yao et al. 2024 CacheBlend; Liu et al. 2023 CacheGen; Juravsky et al. 2024 Hydragen; Kwon et al. 2023 vLLM; Belady 1966; Megiddo & Modha 2003 ARC; Einziger et al. 2017 TinyLFU; Anthropic prompt caching docs (platform.claude.com); Regmi & Pun 2024 GPT Semantic Cache; Li et al. 2024 SCALM; Dai et al. 2024 "SemanticCache" or related; Zhu et al. 2024 "Efficient Prompt Caching via Embedding Similarity".',
  },
  {
    key: 'pipeline-rag',
    title: 'Pipeline RAG (end-to-end retrieval-augmented generation: routing, retrieval, compression, generation, grounding, evaluation)',
    scope: 'Foundational RAG (Lewis et al. 2020, REALM, RETRO), adaptive and self-reflective RAG (Self-RAG, CRAG, Adaptive-RAG, FLARE, IRCoT), hierarchical and graph-based indexing (RAPTOR, GraphRAG), query transformation (query rewriting by Ma et al. 2023, step-back prompting, multi-query, HyDE), context compression and selection (LLMLingua, RECOMP, "Lost in the Middle" position effects), modular RAG taxonomy (Gao et al. 2023 survey and 2024 Modular RAG), failure analysis (Barnett et al. 2024 "Seven Failure Points"), evaluation frameworks (RAGAS, ARES, TruLens-style triads, groundedness and citation precision/recall), long-context vs RAG tradeoffs (Li et al. 2024, Xu et al. 2023), agentic RAG surveys (Singh et al. 2025), citation and attribution (ALCE), and production concerns (chunking strategy, metadata filtering, re-ranking, guardrails, observability).',
    seeds: 'Lewis et al. 2020 RAG; Guu et al. 2020 REALM; Borgeaud et al. 2022 RETRO; Asai et al. 2023 Self-RAG; Yan et al. 2024 Corrective RAG; Jeong et al. 2024 Adaptive-RAG; Jiang et al. 2023 FLARE; Trivedi et al. 2022 IRCoT; Sarthi et al. 2024 RAPTOR; Edge et al. 2024 GraphRAG; Ma et al. 2023 Query Rewriting for RAG; Zheng et al. 2023 Step-Back Prompting; Jiang et al. 2023 LLMLingua; Xu et al. 2023 RECOMP; Liu et al. 2023 Lost in the Middle; Gao et al. 2023 RAG survey; Gao et al. 2024 Modular RAG; Barnett et al. 2024 Seven Failure Points; Es et al. 2023 RAGAS; Saad-Falcon et al. 2023 ARES; Gao et al. 2023 ALCE (Enabling LLMs to Generate Text with Citations); Li et al. 2024 Retrieval Augmented Generation or Long-Context LLMs; Singh et al. 2025 Agentic RAG survey; Shi et al. 2023 REPLUG; Lin et al. 2023 RA-DIT.',
  },
  {
    key: 'prompting-techniques',
    title: 'Cross-cutting: Prompting Techniques (for reasoning, structured output, robustness, and prompt optimization)',
    scope: 'Chain-of-thought and zero-shot CoT, few-shot demonstration selection and ordering, self-consistency, role and persona prompting (and evidence on its limits), structured output and schema constraints, instruction placement and long-context ordering, prompt optimization (Automatic Prompt Engineer, OPRO, DSPy compilers, TextGrad), prompt compression, principled instruction design (Bsharat et al. 2023), the Prompt Report taxonomy (Schulhoff et al. 2024), Medprompt-style composition, Self-Discover reasoning structures, meta-prompting, prompt injection and robustness, and prompting guidance for frontier reasoning models (Anthropic prompt engineering documentation: clarity, examples, XML tags, system prompts, chain-of-thought, prompt chaining; OpenAI reasoning model guidance).',
    seeds: 'Wei et al. 2022 Chain-of-Thought; Kojima et al. 2022 Large Language Models are Zero-Shot Reasoners; Wang et al. 2022 Self-Consistency; Zhou et al. 2022 Automatic Prompt Engineer; Yang et al. 2023 OPRO; Khattab et al. 2023 DSPy; Yuksekgonul et al. 2024 TextGrad; Schulhoff et al. 2024 The Prompt Report; Bsharat et al. 2023 Principled Instructions Are All You Need; Nori et al. 2023 Medprompt; Zhou et al. 2024 Self-Discover; Min et al. 2022 Rethinking the Role of Demonstrations; Lu et al. 2021 Fantastically Ordered Prompts; Liu et al. 2023 Lost in the Middle; Jiang et al. 2023 LLMLingua; Sclar et al. 2023 Quantifying Language Models Sensitivity to Spurious Features in Prompt Design; Zheng et al. 2023 Is "A Helpful Assistant" the Best Role?; Anthropic prompt engineering docs; Suzgun & Kalai 2024 Meta-Prompting.',
  },
  {
    key: 'pipeline-architecture',
    title: 'Cross-cutting: Pipeline Architecture and Efficiency (compound AI systems, routing, cascades, agent patterns, observability, failure taxonomy)',
    scope: 'Compound AI systems and agentic workflow patterns (Zaharia et al. 2024 BAIR "The Shift from Models to Compound AI Systems"; Anthropic "Building Effective Agents" 2024: prompt chaining, routing, parallelization, orchestrator-workers, evaluator-optimizer; Andrew Ng agentic design patterns), cost-aware routing and cascades (FrugalGPT, RouteLLM, model cascades, AutoMix, hybrid LLM routing), programmatic composition and optimization (DSPy, LangGraph-style state graphs, Trace), cognitive architectures (CoALA by Sumers et al. 2023), multi-agent frameworks and their failure taxonomy (AutoGen, MetaGPT, Cemri et al. 2025 "Why Do Multi-Agent LLM Systems Fail?"), evaluation rigor (Kapoor et al. 2024 "AI Agents That Matter"), efficiency surveys (Wan et al. 2023 Efficient LLMs survey; Zhou et al. 2024 survey on efficient inference), observability and tracing (OpenTelemetry GenAI semantic conventions), reliability patterns (idempotency, retries, circuit breakers, bulkheads), and guardrails/safety layering (NeMo Guardrails, Llama Guard, constitutional classifiers).',
    seeds: 'Zaharia et al. 2024 Compound AI Systems (BAIR blog); Anthropic 2024 Building Effective Agents; Chen, Zaharia & Zou 2023 FrugalGPT; Ong et al. 2024 RouteLLM; Madaan et al. 2023 AutoMix; Ding et al. 2024 Hybrid LLM routing; Khattab et al. 2023 DSPy; Sumers et al. 2023 CoALA; Wu et al. 2023 AutoGen; Hong et al. 2023 MetaGPT; Cemri et al. 2025 Why Do Multi-Agent LLM Systems Fail; Kapoor et al. 2024 AI Agents That Matter; Wan et al. 2023 Efficient Large Language Models: A Survey; Zhou et al. 2024 A Survey on Efficient Inference for LLMs; Cheng et al. 2024 Trace / "Trace is the Next AutoDiff"; Rebedea et al. 2023 NeMo Guardrails; Inan et al. 2023 Llama Guard; Nygard 2007 Release It!; OpenTelemetry GenAI semantic conventions.',
  },
]

const PAPER = {
  type: 'object',
  properties: {
    title: { type: 'string' },
    authors: { type: 'string', description: 'First author et al., or full list if short' },
    year: { type: 'integer' },
    venue: { type: 'string', description: 'Conference/journal/arXiv/blog/docs' },
    url: { type: 'string', description: 'Canonical URL (arxiv abs page preferred)' },
    arxiv_id: { type: 'string', description: 'e.g. 2305.14283, or empty string if not on arXiv' },
    citation_signal: { type: 'string', description: 'Why this is highly rated: approximate citation count, venue tier, or adoption evidence' },
    key_contribution: { type: 'string', description: '2-4 sentences: what the paper shows, with concrete numbers where reported' },
    design_implication: { type: 'string', description: '2-4 sentences: how this should shape a production implementation of the concept' },
  },
  required: ['title', 'authors', 'year', 'venue', 'url', 'arxiv_id', 'citation_signal', 'key_contribution', 'design_implication'],
}

const TECHNIQUE = {
  type: 'object',
  properties: {
    name: { type: 'string' },
    description: { type: 'string', description: 'Precise algorithmic description, enough to implement from' },
    source_titles: { type: 'array', items: { type: 'string' }, description: 'Titles of papers in the papers list that establish this technique' },
    when_to_use: { type: 'string' },
    tradeoffs: { type: 'string', description: 'Cost, latency, failure modes, quality impact' },
    default_parameters: { type: 'string', description: 'Recommended default hyperparameters/thresholds with justification from literature' },
  },
  required: ['name', 'description', 'source_titles', 'when_to_use', 'tradeoffs', 'default_parameters'],
}

const RESEARCH_SCHEMA = {
  type: 'object',
  properties: {
    concept: { type: 'string' },
    summary: { type: 'string', description: 'A 1-2 paragraph state-of-the-art summary of the concept' },
    papers: { type: 'array', items: PAPER, minItems: 10 },
    techniques: { type: 'array', items: TECHNIQUE, minItems: 6 },
    architecture_recommendations: { type: 'array', items: { type: 'string' }, description: 'Concrete, numbered design recommendations for a production-grade, task-agnostic implementation' },
    pitfalls: { type: 'array', items: { type: 'string' }, description: 'Documented failure modes with the paper that documents them' },
    evaluation_metrics: { type: 'array', items: { type: 'string' } },
    engineering_adaptation_notes: { type: 'array', items: { type: 'string' }, description: 'How the concept adapts to engineering tasks (code, specs, CAD/docs, requirements, incident data, test logs)' },
    composition_notes: { type: 'array', items: { type: 'string' }, description: 'How this concept interacts with the other five: hybrid retrieval, task decomposition, answer verification, parallelization, caching, pipeline RAG' },
  },
  required: ['concept', 'summary', 'papers', 'techniques', 'architecture_recommendations', 'pitfalls', 'evaluation_metrics', 'engineering_adaptation_notes', 'composition_notes'],
}

const CRITIQUE_SCHEMA = {
  type: 'object',
  properties: {
    missing_papers: { type: 'array', items: PAPER, description: 'Seminal or highly-cited works absent from the dossier, each verified to exist via search' },
    missing_techniques: { type: 'array', items: TECHNIQUE },
    corrections: { type: 'array', items: { type: 'string' }, description: 'Factual corrections to claims in the dossier, each stating the evidence' },
    additional_recommendations: { type: 'array', items: { type: 'string' } },
  },
  required: ['missing_papers', 'missing_techniques', 'corrections', 'additional_recommendations'],
}

const VERIFY_SCHEMA = {
  type: 'object',
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          title: { type: 'string' },
          exists: { type: 'boolean' },
          metadata_correct: { type: 'boolean' },
          claim_accurate: { type: 'boolean', description: 'Is the key_contribution claim faithful to the actual paper?' },
          corrected_title: { type: 'string' },
          corrected_authors: { type: 'string' },
          corrected_year: { type: 'integer' },
          corrected_venue: { type: 'string' },
          corrected_url: { type: 'string' },
          corrected_arxiv_id: { type: 'string' },
          corrected_key_contribution: { type: 'string', description: 'Empty if the original claim was accurate' },
          evidence: { type: 'string', description: 'URL(s) checked and what they showed' },
        },
        required: ['title', 'exists', 'metadata_correct', 'claim_accurate', 'corrected_title', 'corrected_authors', 'corrected_year', 'corrected_venue', 'corrected_url', 'corrected_arxiv_id', 'corrected_key_contribution', 'evidence'],
      },
    },
  },
  required: ['results'],
}

const TOOLING = `You have web access: first call ToolSearch with query "select:WebSearch,WebFetch" to load those tools, then use WebSearch (mode "extended" for niche or recent facts) and WebFetch (arxiv.org abs pages, aclanthology.org, openreview.net, proceedings pages, official docs) to confirm every fact you report. Never report a paper you did not confirm exists via a fetched or searched page. Every URL must be one you actually saw in a search result or fetched page. Prefer arXiv abs URLs in the form https://arxiv.org/abs/XXXX.XXXXX.`

function researchPrompt(c) {
  return `You are a senior research engineer compiling a literature dossier for a company building a production, task-agnostic AI pipeline component.

CONCEPT: ${c.title}

SCOPE TO COVER: ${c.scope}

CANDIDATE WORKS TO CHECK (seed list, not exhaustive, each must be verified before inclusion and may be dropped if wrong): ${c.seeds}

${TOOLING}

Requirements:
1. Find at least 12 highly rated sources: top-venue papers (NeurIPS, ICML, ICLR, ACL, EMNLP, NAACL, SIGIR, OSDI, SOSP, Nature), widely cited arXiv preprints (hundreds of citations or clear industry adoption), and authoritative engineering documentation (Anthropic, OpenAI, vLLM, SGLang docs/blogs) where they define the state of practice. Include the foundational classics the field builds on.
2. For each paper, state concretely what it shows (numbers where reported: accuracy gains, latency reductions, cost reductions, benchmark names) and the specific implication for implementing this component in production.
3. Extract at least 6 implementable techniques with algorithmic detail and literature-justified default parameters (e.g. RRF k=60; self-consistency sample counts; semantic cache similarity thresholds; reranker depth).
4. Give architecture recommendations for a component that: is pluggable into a larger pipeline, accepts a natural-language task prompt, reasons about how to execute it, exposes configuration for any domain, and is adaptable to engineering workloads (code, specifications, requirements, standards documents, test logs, incident reports, CAD/BOM metadata).
5. List pitfalls documented in the literature and how to mitigate them.
6. Note how this concept composes with the other five pipeline components (hybrid retrieval, task decomposition, answer verification, parallelization, caching, pipeline RAG) and with prompting/architecture best practices.

Be exhaustive and precise. Return the structured dossier.`
}

function critiquePrompt(c, dossier) {
  return `You are a skeptical senior reviewer auditing a literature dossier for completeness and accuracy.

CONCEPT: ${c.title}
SCOPE: ${c.scope}

${TOOLING}

DOSSIER UNDER REVIEW (JSON):
${JSON.stringify(dossier, null, 1)}

Your job:
1. Identify seminal or very highly cited works in this scope that are MISSING. Think across: the foundational pre-LLM work the field relies on, the 2020-2024 breakthrough papers, 2024-2026 state-of-the-art, and authoritative production documentation. Search the web to confirm each candidate exists and gather its real metadata before adding it. Add at least 3 if they genuinely exist; add zero only if you searched and the dossier is truly complete.
2. Identify techniques that are implementable and important but absent.
3. Check the dossier's factual claims (numbers, venues, years, what a paper actually showed) and list corrections with evidence. Be specific: quote the wrong claim and give the right one.
4. Add further architecture recommendations where the dossier is thin on production concerns (observability, failure handling, cost control, security/prompt-injection, evaluation).

Return the structured critique.`
}

function verifyPrompt(c, papers) {
  return `You are a citation verifier. For EVERY paper below, confirm it exists, that its metadata is correct, and that the key_contribution claim is faithful to the actual work. Be adversarial: assume errors until proven otherwise.

${TOOLING}

Procedure per paper: search for the exact title (quoted) and first author; fetch the arXiv abs page or venue page; compare title, authors, year, venue, arXiv id; read the abstract and confirm the key_contribution claim, including any numbers. If the paper does not exist or cannot be found after two distinct searches, set exists=false. If a claim is exaggerated, misattributed, or numbers are wrong, set claim_accurate=false and supply corrected_key_contribution. Fill every corrected_* field with the verified value (copy the original when already correct). Return one result per input paper, in the same order, same count.

CONCEPT: ${c.title}

PAPERS (JSON):
${JSON.stringify(papers, null, 1)}`
}

function mergeDossier(dossier, critique) {
  if (!dossier) return null
  const d = { ...dossier }
  if (critique) {
    const titles = new Set(d.papers.map(p => p.title.toLowerCase().trim()))
    const added = (critique.missing_papers || []).filter(p => !titles.has(p.title.toLowerCase().trim()))
    d.papers = [...d.papers, ...added]
    const tnames = new Set(d.techniques.map(t => t.name.toLowerCase().trim()))
    d.techniques = [...d.techniques, ...(critique.missing_techniques || []).filter(t => !tnames.has(t.name.toLowerCase().trim()))]
    d.architecture_recommendations = [...d.architecture_recommendations, ...(critique.additional_recommendations || [])]
    d.critique_corrections = critique.corrections || []
    d.critique_added_paper_count = added.length
  }
  return d
}

function applyVerification(dossier, verification) {
  if (!dossier) return null
  const d = { ...dossier }
  const results = (verification && verification.results) || []
  const byTitle = new Map(results.map(r => [r.title.toLowerCase().trim(), r]))
  const kept = []
  const dropped = []
  for (const p of d.papers) {
    const r = byTitle.get(p.title.toLowerCase().trim())
    if (!r) { kept.push({ ...p, verification: 'unverified' }); continue }
    if (!r.exists) { dropped.push({ title: p.title, reason: r.evidence }); continue }
    kept.push({
      ...p,
      title: r.corrected_title || p.title,
      authors: r.corrected_authors || p.authors,
      year: r.corrected_year || p.year,
      venue: r.corrected_venue || p.venue,
      url: r.corrected_url || p.url,
      arxiv_id: r.corrected_arxiv_id !== undefined ? r.corrected_arxiv_id : p.arxiv_id,
      key_contribution: (!r.claim_accurate && r.corrected_key_contribution) ? r.corrected_key_contribution : p.key_contribution,
      verification: r.claim_accurate && r.metadata_correct ? 'verified' : 'verified-corrected',
      verification_evidence: r.evidence,
    })
  }
  d.papers = kept
  d.dropped_papers = dropped
  return d
}

log(`Researching ${CONCEPTS.length} concepts: research -> critique -> verify, pipelined per concept`)

const results = await pipeline(
  CONCEPTS,
  c => agent(researchPrompt(c), { label: `research:${c.key}`, phase: 'Research', schema: RESEARCH_SCHEMA, effort: 'high' }),
  async (dossier, c) => {
    if (!dossier) { log(`${c.key}: research returned nothing`); return null }
    log(`${c.key}: ${dossier.papers.length} papers, ${dossier.techniques.length} techniques; critiquing`)
    const critique = await agent(critiquePrompt(c, dossier), { label: `critique:${c.key}`, phase: 'Critique', schema: CRITIQUE_SCHEMA, effort: 'high' })
    const merged = mergeDossier(dossier, critique)
    log(`${c.key}: critic added ${merged.critique_added_paper_count || 0} papers, ${(critique && critique.corrections || []).length} corrections`)
    return merged
  },
  async (merged, c) => {
    if (!merged) return null
    const half = Math.ceil(merged.papers.length / 2)
    const chunks = [merged.papers.slice(0, half), merged.papers.slice(half)].filter(ch => ch.length)
    const verifications = await parallel(chunks.map((ch, i) => () =>
      agent(verifyPrompt(c, ch), { label: `verify:${c.key}:${i + 1}`, phase: 'Verify', schema: VERIFY_SCHEMA, effort: 'high' })))
    const combined = { results: verifications.filter(Boolean).flatMap(v => v.results) }
    const final = applyVerification(merged, combined)
    log(`${c.key}: ${final.papers.length} papers kept, ${final.dropped_papers.length} dropped as unverifiable`)
    return { key: c.key, title: c.title, dossier: final }
  },
)

const out = {}
for (const r of results.filter(Boolean)) out[r.key] = r
const missing = CONCEPTS.map(c => c.key).filter(k => !out[k])
if (missing.length) log(`WARNING: no result for ${missing.join(', ')}`)
return { concepts: out, missing }

