cd "/c/Users/kenne/.claude/projects/C--Users-kenne-Documents-Prebuilt-AI-Technique-Models" && python - <<'EOF'
import json, pathlib
def sum_usage(path):
    per = {}
    for line in open(path, encoding="utf-8", errors="replace"):
        try: r=json.loads(line)
        except: continue
        m=r.get("message") or {}
        u=m.get("usage") if isinstance(m,dict) else None
        if not u: continue
        mid=m.get("id") or id(r)
        cur=per.get(mid, {"input":0,"output":0,"cache_read":0,"cache_write":0})
        cur={"input":max(cur["input"],u.get("input_tokens",0) or 0),
             "output":max(cur["output"],u.get("output_tokens",0) or 0),
             "cache_read":max(cur["cache_read"],u.get("cache_read_input_tokens",0) or 0),
             "cache_write":max(cur["cache_write"],u.get("cache_creation_input_tokens",0) or 0)}
        per[mid]=cur
    t={"input":0,"output":0,"cache_read":0,"cache_write":0,"calls":len(per)}
    for v in per.values():
        for k in v: t[k]+=v[k]
    return t
main=sum_usage(pathlib.Path("05a19eb0-51c5-4be5-a66e-6d8ba4e1b8d4.jsonl"))
root=pathlib.Path("05a19eb0-51c5-4be5-a66e-6d8ba4e1b8d4")
sub={"input":0,"output":0,"cache_read":0,"cache_write":0,"calls":0}; n=0
for a in root.rglob("agent-*.jsonl"):
    u=sum_usage(a)
    if u["calls"]: n+=1
    for k in sub: sub[k]+=u[k]
for name,t in (("main",main),("subagents",sub)):
    total=t["input"]+t["output"]+t["cache_read"]+t["cache_write"]
    print(f"{name}: model calls={t['calls']:,} input={t['input']:,} output={t['output']:,} cache_read={t['cache_read']:,} cache_write={t['cache_write']:,} total_processed={total:,}")
print("subagents with activity:", n)
EOF

