const TOOLING = `You have web access: first call ToolSearch with query "select:WebSearch,WebFetch" to load those tools, then use WebSearch (mode "extended" for niche or recent facts) and WebFetch (arxiv.org abs pages, aclanthology.org, openreview.net, proceedings pages, official docs) to confirm every fact you report. Never report a paper you did not confirm exists via a fetched or searched page. Every URL must be one you actually saw in a search result or fetched page. Prefer arXiv abs URLs in the form https://arxiv.org/abs/XXXX.XXXXX.`

function researchPrompt(c) {
  return `You are a senior research engineer compiling a literature dossier for a company building a production, task-agnostic AI pipeline component.

CONCEPT: ${c.title}

SCOPE TO COVER: ${c.scope}

CANDIDATE WORKS TO CHECK (seed list, not exhaustive, each must be verified before inclusion and may be dropped if wrong): ${c.seeds}

${TOOLING}

Requirements:
1. Find at least 12 highly rated sources: top-venue papers (NeurIPS, ICML, ICLR, ACL, EMNLP, NAACL, SIGIR, OSDI, SOSP, Nature), widely cited arXiv preprints (hundreds of citations or clear industry adoption), and authoritative engineering documentation (Anthropic, OpenAI, vLLM, SGLang docs/blogs) where they define the state of practice. Include the foundational classics the field builds on.
2. For each paper, state concretely what it shows (numbers where reported: accuracy gains, latency reductions, cost reductions, benchmark names) and the specific implication for implementing this component in production.
3. Extract at least 6 implementable techniques with algorithmic detail and literature-justified default parameters (e.g. RRF k=60; self-consistency sample counts; semantic cache similarity thresholds; reranker depth).
4. Give architecture recommendations for a component that: is pluggable into a larger pipeline, accepts a natural-language task prompt, reasons about how to execute it, exposes configuration for any domain, and is adaptable to engineering workloads (code, specifications, requirements, standards documents, test logs, incident reports, CAD/BOM metadata).
5. List pitfalls documented in the literature and how to mitigate them.
6. Note how this concept composes with the other five pipeline components (hybrid retrieval, task decomposition, answer verification, parallelization, caching, pipeline RAG) and with prompting/architecture best practices.

Be exhaustive and precise. Return the structured dossier.`
}

function critiquePrompt(c, dossier) {
  return `You are a skeptical senior reviewer auditing a literature dossier for completeness and accuracy.

CONCEPT: ${c.title}
SCOPE: ${c.scope}

${TOOLING}

DOSSIER UNDER REVIEW (JSON):
${JSON.stringify(dossier, null, 1)}

Your job:
1. Identify seminal or very highly cited works in this scope that are MISSING. Think across: the foundational pre-LLM work the field relies on, the 2020-2024 breakthrough papers, 2024-2026 state-of-the-art, and authoritative production documentation. Search the web to confirm each candidate exists and gather its real metadata before adding it. Add at least 3 if they genuinely exist; add zero only if you searched and the dossier is truly complete.
2. Identify techniques that are implementable and important but absent.
3. Check the dossier's factual claims (numbers, venues, years, what a paper actually showed) and list corrections with evidence. Be specific: quote the wrong claim and give the right one.
4. Add further architecture recommendations where the dossier is thin on production concerns (observability, failure handling, cost control, security/prompt-injection, evaluation).

Return the structured critique.`
}

function verifyPrompt(c, papers) {
  return `You are a citation verifier. For EVERY paper below, confirm it exists, that its metadata is correct, and that the key_contribution claim is faithful to the actual work. Be adversarial: assume errors until proven otherwise.

${TOOLING}

Procedure per paper: search for the exact title (quoted) and first author; fetch the arXiv abs page or venue page; compare title, authors, year, venue, arXiv id; read the abstract and confirm the key_contribution claim, including any numbers. If the paper does not exist or cannot be found after two distinct searches, set exists=false. If a claim is exaggerated, misattributed, or numbers are wrong, set claim_accurate=false and supply corrected_key_contribution. Fill every corrected_* field with the verified value (copy the original when already correct). Return one result per input paper, in the same order, same count.

CONCEPT: ${c.title}

PAPERS (JSON):
${JSON.stringify(papers, null, 1)}`
}

function mergeDossier(dossier, critique) {
  if (!dossier) return null
  const d = { ...dossier }
  if (critique) {
    const titles = new Set(d.papers.map(p => p.title.toLowerCase().trim()))
    const added = (critique.missing_papers || []).filter(p => !titles.has(p.title.toLowerCase().trim()))
    d.papers = [...d.papers, ...added]
    const tnames = new Set(d.techniques.map(t => t.name.toLowerCase().trim()))
    d.techniques = [...d.techniques, ...(critique.missing_techniques || []).filter(t => !tnames.has(t.name.toLowerCase().trim()))]
    d.architecture_recommendations = [...d.architecture_recommendations, ...(critique.additional_recommendations || [])]
    d.critique_corrections = critique.corrections || []
    d.critique_added_paper_count = added.length
  }
  return d
}

function applyVerification(dossier, verification) {
  if (!dossier) return null
  const d = { ...dossier }
  const results = (verification && verification.results) || []
  const byTitle = new Map(results.map(r => [r.title.toLowerCase().trim(), r]))
  const kept = []
  const dropped = []
  for (const p of d.papers) {
    const r = byTitle.get(p.title.toLowerCase().trim())
    if (!r) { kept.push({ ...p, verification: 'unverified' }); continue }
    if (!r.exists) { dropped.push({ title: p.title, reason: r.evidence }); continue }
    kept.push({
      ...p,
      title: r.corrected_title || p.title,
      authors: r.corrected_authors || p.authors,
      year: r.corrected_year || p.year,
      venue: r.corrected_venue || p.venue,
      url: r.corrected_url || p.url,
      arxiv_id: r.corrected_arxiv_id !== undefined ? r.corrected_arxiv_id : p.arxiv_id,
      key_contribution: (!r.claim_accurate && r.corrected_key_contribution) ? r.corrected_key_contribution : p.key_contribution,
      verification: r.claim_accurate && r.metadata_correct ? 'verified' : 'verified-corrected',
      verification_evidence: r.evidence,
    })
  }
  d.papers = kept
  d.dropped_papers = dropped
  return d
}

log(`Researching ${CONCEPTS.length} concepts: research -> critique -> verify, pipelined per concept`)

const results = await pipeline(
  CONCEPTS,
  c => agent(researchPrompt(c), { label: `research:${c.key}`, phase: 'Research', schema: RESEARCH_SCHEMA, effort: 'high' }),
  async (dossier, c) => {
    if (!dossier) { log(`${c.key}: research returned nothing`); return null }
    log(`${c.key}: ${dossier.papers.length} papers, ${dossier.techniques.length} techniques; critiquing`)
    const critique = await agent(critiquePrompt(c, dossier), { label: `critique:${c.key}`, phase: 'Critique', schema: CRITIQUE_SCHEMA, effort: 'high' })
    const merged = mergeDossier(dossier, critique)
    log(`${c.key}: critic added ${merged.critique_added_paper_count || 0} papers, ${(critique && critique.corrections || []).length} corrections`)
    return merged
  },
  async (merged, c) => {
    if (!merged) return null
    const half = Math.ceil(merged.papers.length / 2)
    const chunks = [merged.papers.slice(0, half), merged.papers.slice(half)].filter(ch => ch.length)
    const verifications = await parallel(chunks.map((ch, i) => () =>
      agent(verifyPrompt(c, ch), { label: `verify:${c.key}:${i + 1}`, phase: 'Verify', schema: VERIFY_SCHEMA, effort: 'high' })))
    const combined = { results: verifications.filter(Boolean).flatMap(v => v.results) }
    const final = applyVerification(merged, combined)
    log(`${c.key}: ${final.papers.length} papers kept, ${final.dropped_papers.length} dropped as unverifiable`)
    return { key: c.key, title: c.title, dossier: final }
  },
)

const out = {}
for (const r of results.filter(Boolean)) out[r.key] = r
const missing = CONCEPTS.map(c => c.key).filter(k => !out[k])
if (missing.length) log(`WARNING: no result for ${missing.join(', ')}`)
return { concepts: out, missing }

